option = {
        name = nesnd_canon_diplomacy.1.a
        trigger = { nesnd_canon_reply_valid = yes nesnd_canon_request_eligible = yes }
        custom_tooltip = nesnd_canon_accept_request_tt
        hidden_effect = { nesnd_canon_accept_request = yes }
        ai_chance = {
            base = 40
            modifier = { add = 40 trigger_if = { limit = { exists = scope:canon_sender } "relations(scope:canon_sender)" >= 50 } trigger_else = { always = no } }
            modifier = { factor = 0 trigger_if = { limit = { exists = scope:canon_sender } has_attitude = { who = scope:canon_sender attitude = antagonistic } } trigger_else = { always = no } }
        }
    }

option = { name = nesnd_small_states.10.suppress trigger = { nesnd_small_episode_valid = yes nesnd_small_political = yes institution_investment_level = { institution = institution_police value >= 1 } NOT = { has_variable = nesnd_small_episode_choice } }
 custom_tooltip = nesnd_small_states.10.suppress_tt hidden_effect = { nesnd_small_suppress_episode = yes }
 ai_chance = { base = 20 modifier = { add = 20 ig:ig_landowners = { is_in_government = yes } } } }

option = { name = nesnd_canon_diplomacy.1.a trigger = { nesnd_canon_reply_valid = yes nesnd_canon_request_eligible = yes }
 custom_tooltip = nesnd_small_accept_tt hidden_effect = { nesnd_small_accept_request = yes }
 ai_chance = {
  base = 30
  modifier = { trigger = { OR = { NOT = { exists = scope:canon_sender } NOT = { exists = scope:canon_partner } NOT = { exists = scope:canon_kind } } } add = -30 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } scope:canon_kind = 6 } trigger_else = { always = no } } add = -5 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } scope:canon_kind = 7 } trigger_else = { always = no } } add = -22 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } scope:canon_kind = 8 } trigger_else = { always = no } } add = 15 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } "relations(scope:canon_sender)" >= 50 } trigger_else = { always = no } } add = 20 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } OR = { in_default = yes is_at_war = yes } } trigger_else = { always = no } } add = 15 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } OR = { scope:canon_kind = 6 scope:canon_kind = 7 } scope:canon_sender = { nesnd_small_reliable_support = yes } } trigger_else = { always = no } } add = 20 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } OR = { scope:canon_kind = 6 scope:canon_kind = 7 scope:canon_kind = 8 } scope:canon_sender = { economic_dependence = { target = scope:canon_partner value < 0.8 } } } trigger_else = { always = no } } add = 15 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } OR = { scope:canon_kind = 6 scope:canon_kind = 7 scope:canon_kind = 8 } scope:canon_sender = { economic_dependence = { target = scope:canon_partner value > 1.2 } } } trigger_else = { always = no } } add = -20 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } OR = { AND = { scope:canon_kind = 7 scope:canon_sender = { nesnd_small_army_ratio >= 0.6 } } AND = { scope:canon_kind = 6 scope:canon_sender = { nesnd_small_army_ratio >= 0.4 } } } } trigger_else = { always = no } } add = 20 }
  modifier = { trigger = { trigger_if = { limit = { exists = scope:canon_sender exists = scope:canon_partner exists = scope:canon_kind } OR = { scope:canon_kind = 6 scope:canon_kind = 7 } scope:canon_sender = { nesnd_small_gdp_ratio >= 0.4 } } trigger_else = { always = no } } add = 10 }
  # Literal corrections implement the approved 1..95 clamp over the reachable raw scores.
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = -12 } add = 13 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = -2 } add = 3 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 98 } add = -3 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 100 } add = -5 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 103 } add = -8 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 105 } add = -10 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 108 } add = -13 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 110 } add = -15 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 115 } add = -20 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 120 } add = -25 }
  modifier = { trigger = { nesnd_small_reply_acceptance_raw = 125 } add = -30 }
 } }

